Tool schema:
{
  "name": "plan_delivery",
  "description": "Plan the stops of a delivery route. Give either `driver.email` or `driver.phone`, but not both and not neither. Adding up `parcels` over every entry of `stops` must give `load_total`. `window_end` must exceed `window_start` in all entries of `stops`.",
  "parameters": {
    "type": "object",
    "properties": {
      "ship_date": {"type": "string", "format": "date", "description": "Day on which the goods leave the depot."},
      "zone": {"type": "string", "enum": ["domestic", "export"], "description": "Customs zone of the delivery."},
      "customs_code": {"type": "string", "description": "Customs declaration code."},
      "fragile": {"type": "boolean", "description": "Whether the goods are fragile."},
      "approver": {"type": "string", "description": "Person who approved the request."},
      "region": {"type": "string", "enum": ["north", "south", "east", "west", "central"], "description": "Sales region."},
      "urgent": {"type": "boolean", "description": "Whether the request is urgent."},
      "notify": {"type": "boolean", "description": "Whether the requester is notified."},
      "language": {"type": "string", "enum": ["en", "de", "fr", "nl"], "description": "Language of the confirmation, as a two-letter ISO 639-1 code."},
      "driver": {
        "type": "object",
        "description": "Driver of the route.",
        "required": ["name"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "description": "Full name."},
          "email": {"type": "string", "description": "E-mail address."},
          "phone": {"type": "string", "description": "Phone number."}
        }
      },
      "stops": {
        "type": "array",
        "description": "Stops of the route.",
        "minItems": 1,
        "maxItems": 8,
        "items": {
          "type": "object",
          "required": ["stop_id", "parcels", "window_start", "window_end"],
          "additionalProperties": false,
          "properties": {
            "stop_id": {"type": "string", "description": "Identifier of the stop."},
            "parcels": {"type": "integer", "minimum": 1, "maximum": 40, "description": "Number of parcels for the stop."},
            "window_start": {"type": "integer", "minimum": 0, "maximum": 23, "description": "Hour at which delivery may start."},
            "window_end": {"type": "integer", "minimum": 1, "maximum": 24, "description": "Hour by which delivery must be done."},
            "signature": {"type": "boolean", "description": "Whether a signature is required."}
          }
        }
      },
      "load_total": {"type": "integer", "minimum": 0, "description": "Total number of parcels of all stops."}
    },
    "required": ["zone", "approver", "language", "driver", "stops", "load_total"],
    "additionalProperties": false
  }
}

