Tool schema:
{
  "name": "file_claim",
  "description": "File an insurance claim with a list of cost items. The value of `claimed_total` is the total of `amount` over all entries of `expenses`; it has to match exactly.",
  "parameters": {
    "type": "object",
    "properties": {
      "reference": {"type": "string", "description": "Reference of the requester."},
      "region": {"type": "string", "enum": ["north", "south", "east", "west", "central"], "description": "Sales region."},
      "memo": {"type": "string", "description": "Short memo for the records."},
      "expenses": {
        "type": "array",
        "description": "Cost items of the claim.",
        "minItems": 1,
        "maxItems": 5,
        "items": {
          "type": "object",
          "required": ["item_ref", "kind", "amount"],
          "additionalProperties": false,
          "properties": {
            "item_ref": {"type": "string", "description": "Reference of the cost item."},
            "kind": {"type": "string", "enum": ["travel", "repair", "medical", "other"], "description": "Kind of cost."},
            "amount": {"type": "number", "minimum": 1, "maximum": 2000, "description": "Amount of the cost item."},
            "receipt": {"type": "boolean", "description": "Whether a receipt is attached."}
          }
        }
      },
      "currency": {"type": "string", "enum": ["EUR", "USD", "GBP"], "description": "Currency of all prices and amounts of the entries."},
      "claimed_total": {"type": "number", "minimum": 0, "description": "Total of all cost items in the given currency."}
    },
    "required": ["reference", "region", "expenses", "currency", "claimed_total"],
    "additionalProperties": false
  }
}

